import { InfiniteData, useInfiniteQuery, useQueryClient } from '@tanstack/react-query';
import axios from 'axios';
import { produce } from 'immer';
import { useCallback } from 'react';
import { DEFAULT_NOTIFICATION_PAGING } from '~/entities/notification/model/constants';
import { NotificationListParams, NotificationListResponse } from '~/entities/notification/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { InfiniteQueryOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { queries } from '~/shared/api/query-keys';
import { resultify } from '~/shared/lib/utils/resultify';

export const getNotificationList = ({ paging, search }: NotificationListParams) => {
  return resultify(
    axios.post<NotificationListResponse>(`${API_URLS.notificationList}`, {
      paging,
      search,
    }),
  );
};

export const useNotificationListInfiniteQuery = (
  { paging = DEFAULT_NOTIFICATION_PAGING, search }: NotificationListParams,
  options?: InfiniteQueryOptions<
    NotificationListResponse,
    CBDCAxiosError,
    InfiniteData<NotificationListResponse>,
    readonly unknown[],
    NotificationListParams
  >,
) => {
  const queryClient = useQueryClient();

  const markAsRead = useCallback(
    async (messageId: string) => {
      try {
        queryClient.setQueriesData(
          { queryKey: queries.notification.notificationList._def },
          produce((draft: InfiniteData<NotificationListResponse> | undefined) => {
            if (!draft) return;

            draft.pages.forEach((page) => {
              if (page.result?.list) {
                page.result.list.forEach((item) => {
                  if (item.mssageManageId === messageId) {
                    item.isRead = true;
                  }
                });
              }
            });
          }),
        );
      } catch (error) {
        console.error('Failed to mark as read:', error);
        throw error;
      }
    },
    [queryClient],
  );

  const query = useInfiniteQuery<
    NotificationListResponse,
    CBDCAxiosError,
    InfiniteData<NotificationListResponse>,
    readonly unknown[],
    NotificationListParams
  >({
    queryKey: queries.notification.notificationList({ paging, search }).queryKey,
    queryFn: async ({ pageParam = { paging, search } }) => {
      const response = await getNotificationList(pageParam);

      // Get all existing queries with the same base key
      const existingQueries = queryClient.getQueriesData<InfiniteData<NotificationListResponse>>({
        queryKey: queries.notification.notificationList._def,
      });

      // Combine all items from all queries
      const allExistingItems = existingQueries.flatMap(
        ([_, data]) => data?.pages.flatMap((page) => page.result?.list || []) || [],
      );

      if (response.result?.list) {
        response.result.list = response.result.list.map((item) => ({
          ...item,
          // Check against all existing items
          isRead: allExistingItems.some(
            (existing) => existing.mssageManageId === item.mssageManageId && existing.isRead,
          ),
        }));
      }

      return response;
    },
    initialPageParam: { paging, search },
    getNextPageParam: (lastPage) => {
      if (
        Number(lastPage?.result?.paging?.totalPageCount ?? 0) <= Number(lastPage?.result?.paging?.currentPageNo ?? 0)
      ) {
        return undefined;
      }
      return {
        paging: {
          ...paging,
          currentPageNo: (lastPage.result.paging?.currentPageNo ?? 1) + 1,
        },
        search,
      };
    },
    staleTime: 0,
    gcTime: Infinity,
    enabled: !!paging && !!search,
    ...options,
  });

  return { ...query, markAsRead };
};
